last = [x for x in m if x['kind'] == 'text' and x['id'] == 'history'][-1]['value']
md = last['md']
REP = [
    ('Окремо стоять Круки з Розкошівки на Вінниччині — родина бабусі по батькові.',
     'Окремо стоять Гакало із Залужжя на Вінниччині — родина бабусі по батькові.'),
    ('Його дружиною стала [[p:nina|Ніна Гивівна Крук]] (2 лютого 1942 — 9 лютого 2013), родом з Розкошівки на Вінниччині (про її родину — в розділі «Круки»).',
     'Його дружиною стала [[p:nina|Ніна Гивівна]] (2 лютого 1942 — 9 лютого 2013), у дівоцтві Гакало, у першому шлюбі Крук, родом із Залужжя на Вінниччині (про її родину — в розділі «Гакало із Залужжя»). За словами Максима, офіційно Шутою вона не була.'),
    ('**Гива Крук** — повне ім\'я в документах, звідки він родом, де служив. Шукати в повоєнних списках священників, в архіві СБУ; розпитати тьотю Тоню.',
     '**Гива Купріянович Гакало** (1903) — коли помер і де похований; метрика 1903 р. (Залужжя); його батьки й брати (Є припущення: Іван Купріянович, 1895); хто такий Володимир з фото 1979 р.; розпитати тьотю Тоню.'),
]
for a, b in REP:
    assert md.count(a) == 1, a
    md = md.replace(a, b)
i = md.index('### Круки з Розкошівки'); j = md.index('### Дергачови і Грищенки')
SEC = ('### Гакало із Залужжя\n\n'
       'Бабуся Максима по батькові, [[p:nina|Ніна Гивівна]], народилася 2 лютого 1942 року в селі Залужжя Теплицького району на Вінниччині (сусіднє село — Розкошівка). Її свідоцтво про народження відновили лише 1956 року: запис № 466 від 9 серпня 1956 р. у Теплицькому РАЦС ([[d:hak56|свідоцтво 1956]], [[d:hak70|повторне 1970]]). У ньому батьки — [[p:hyva|Гива Каприянович Гакало]] і [[p:anna_hak|Анна Григорівна Гакало]], обоє українці. Її старша сестра — [[p:antonina|Антоніна (Тоня)]], за спогадами, живе в Розкошівці.\n\n'
       '5 травня 1960 року в Теплику Ніна вийшла заміж за [[p:andrii_kruk|Андрія Івановича Крука]] (1936 р. н., із с. Будьки Жмеринського району) і взяла його прізвище ([[d:hak60|свідоцтво про одруження]]). Під прізвищем Крук вона й записана в паспорті, виданому 1997 р. в Бобровицькому районі на Чернігівщині ([[d:hak97|копія паспорта]]). Раніше на сайті Крук помилково вважали прізвищем її батька.\n\n'
       'Батько Ніни, Гива Купріянович Гакало, народився 1903 року в Залужжі. У Другу світову його призвав Тепликський райвійськкомат; він був писарем начальника фінансового забезпечення 453-го стрілецького полку 78-ї стрілецької дивізії. Наказом по полку від 16 травня 1945 р. його нагородили медаллю «За бойові заслуги»: разом з начфіном він видавав грошове забезпечення прямо в підрозділах, «часто под огнем противника» ([[d:hakpn45|наказ 1945]]). 1985 року його внесено до ювілейної картотеки — орден Вітчизняної війни II ступеня ([[d:hakpnk|картка «Пам\'яті народу»]]). За родинним переказом, він був священником, але документи цього не підтверджують, і, за словами Максима, священником він не був.\n\n'
       'Батька Гиви звали Купріян (за по батькові). Є припущення, що [[p:ivan_hak|Іван Купріянович Гакало]] (1895), теж призваний Тепликським райвійськкоматом, — брат Гиви (на підставі по батькові й того самого військкомату).\n\n'
       'Серед документів Ніни є фото військового з написом «Милій Мамі, Татові, братіку Васі і бабці, сестричці Катрусі… Ваш син Володимир», 18 грудня 1979 р. ([[d:hakvol79|фото й напис]]). Є припущення, що Володимир — її син; хто він — уточнюємо в родини.\n\n')
md = md[:i] + SEC + md[j:]
